import os
from pathlib import Path
import json
from datetime import datetime
from ravl.common.llm.llm_providers import LLMProviderFactory

def read_files(directory):
    """Reads all text files from a directory into a list of strings."""
    file_contents = []
    for filename in os.listdir(directory):
        if filename.endswith(".txt") or filename.endswith(".md"):  # Added .md support
            filepath = os.path.join(directory, filename)
            try:
                with open(filepath, "r", encoding="utf-8") as f:
                    file_contents.append(f.read())
            except Exception as e:
                print(f"Error reading file {filename}: {e}")  # More informative error
    return file_contents

def generate_report(risk_gaps, opportunity_gaps):
    """Generates an HTML report from the risk and opportunity gaps."""
    html = f"""
    <!DOCTYPE html>
    <html>
    <head>
        <title>Delivery Forum Report</title>
        <style>
            body {{
                font-family: Arial, sans-serif;
                margin: 20px;
            }}
            h1, h2 {{
                color: #333;
            }}
            .gap {{
                margin-bottom: 15px;
                padding: 10px;
                border: 1px solid #ddd;
                background-color: #f9f9f9;
            }}
            .gap-title {{
                font-weight: bold;
                margin-bottom: 5px;
            }}
            .gap-person {{
                font-style: italic;
                color: #777;
            }}
        </style>
    </head>
    <body>
        <h1>Delivery Forum Report</h1>
        <h2>Top 10 Risk Gaps</h2>
    """
    for gap in risk_gaps:
        html += f"""
        <div class="gap">
            <div class="gap-title">{gap['gap']}</div>
            <div class="gap-person">Assigned to: {gap['person']}</div>
        </div>
        """

    html += """
        <h2>Top 10 Missed Opportunity Gaps</h2>
    """
    for gap in opportunity_gaps:
        html += f"""
        <div class="gap">
            <div class="gap-title">{gap['gap']}</div>
            <div class="gap-person">Assigned to: {gap['person']}</div>
        </div>
        """

    html += """
    </body>
    </html>
    """
    return html

def main():
    # Get loop directories from environment (set by framework)
    loop_dir = Path(os.environ.get('RAVL_LOOP_DIR'))
    output_dir = loop_dir / "output"
    output_dir.mkdir(parents=True, exist_ok=True) #Make sure output directory exists

    coordination_dir = "/Users/sand-mbp-002/Library/CloudStorage/GoogleDrive-ktrethewey@sandtech.com/Shared drives/Sand.Delivery.DigitalTerrain/delivery-function/context/coordination"
    strategy_dir = "/Users/sand-mbp-002/Library/CloudStorage/GoogleDrive-ktrethewey@sandtech.com/Shared drives/Sand.Delivery.DigitalTerrain/delivery-function/context/strategy"

    coordination_files = read_files(coordination_dir)
    strategy_files = read_files(strategy_dir)
    all_context = "\n".join(coordination_files + strategy_files)

    # Use the framework's configured LLM provider
    provider = LLMProviderFactory.create_provider("google (gemini-2.0-flash-exp)")

    prompt = f"""
    Analyze the following context to identify the top 10 possible risk gaps and top 10 possible missed opportunity gaps.
    Assign each gap to a person best positioned to respond (options: Kevin, Sandra, Ashley, or David).
    Focus on impact and outcomes rather than process and reporting risks and opportunities.
    Ignore missing data, assume everyone's doing their best - mine the data for insights.

    Context:
    {all_context}

    Respond with a JSON object with two keys: "risk_gaps" and "opportunity_gaps".
    Each should be a list of dictionaries with "gap" and "person" keys.
    Example:
    {{
        "risk_gaps": [
            {{
                "gap": "Lack of clear ownership for key deliverables",
                "person": "Kevin"
            }},
            {{
                "gap": "Potential delays due to unmitigated dependencies",
                "person": "Sandra"
            }}
        ],
        "opportunity_gaps":[
            {{
                "gap": "Untapped potential for cross-functional collaboration",
                "person": "Ashley"
            }},
            {{
                "gap": "Missed opportunities to leverage emerging technologies",
                "person": "David"
            }}
        ]
    }}
    """

    print("Making LLM call to identify risk and opportunity gaps...")
    response = provider.complete(prompt, max_tokens=8192)
    print("LLM call complete.")

    try:
        data = json.loads(response)
        risk_gaps = data["risk_gaps"]
        opportunity_gaps = data["opportunity_gaps"]
    except (json.JSONDecodeError, KeyError) as e:
        print(f"Error decoding LLM response: {e}. Response was: {response}")
        risk_gaps = []
        opportunity_gaps = []

    # Generate HTML report
    print("Generating HTML report...")
    html_report = generate_report(risk_gaps, opportunity_gaps)

    # Save the report
    now = datetime.now()
    timestamp_str = now.strftime("%Y-%m-%d-%H%M")
    output_filename = f"{timestamp_str}-delivery-forum-report.html"
    output_path = output_dir / output_filename

    print(f"Saving report to {output_path}")
    try:
        with open(output_path, "w", encoding="utf-8") as f:
            f.write(html_report)
        print("Report saved successfully.")
    except Exception as e:
        print(f"Error saving report: {e}")

if __name__ == "__main__":
    main()

